test('Codex app-server capability route metadata is derived from matrix rows', () => {
  const { CODEX_APP_SERVER_CAPABILITY_MATRIX } = require('../daemon/src/codex-app-server/capability-matrix');
  const { buildCodexAppServerRouteCapabilities } = require('../daemon/src/codex-app-server/capability-routes');
  const selectedRows = CODEX_APP_SERVER_CAPABILITY_MATRIX.filter((row) => (
    row.daemonOwner === 'server route' &&
    row.direction === 'request' &&
    row.testRequirement === 'route test'
  ));
  const routes = buildCodexAppServerRouteCapabilities();
  assert.equal(routes.length, selectedRows.length);
  for (const route of routes) {
    const row = selectedRows.find((candidate) => candidate.method === route.method);
    assert.ok(row, `${route.method} must be backed by a matrix row`);
    assert.equal(route.localStatus, row.localStatus);
    assert.equal(route.mobileStatus, row.mobileStatus);
    assert.equal(route.risk, row.risk);
    assert.equal(route.source, 'capability-matrix');
  }

  const routeByMethod = new Map(routes.map((route) => [route.method, route]));
  assert.equal(routeByMethod.get('account/read').readOnly, true);
  assert.equal(routeByMethod.get('account/rateLimits/read').readOnly, true);
  assert.equal(routeByMethod.get('account/login/start').readOnly, false);
  assert.equal(routeByMethod.get('account/logout').readOnly, false);
  assert.equal(routeByMethod.get('mcpServer/oauth/login').readOnly, false);
  assert.equal(routeByMethod.get('account/login/start').requiresApproval, true);
  assert.equal(routeByMethod.get('account/logout').requiresApproval, true);
  assert.equal(routeByMethod.get('mcpServer/oauth/login').requiresApproval, true);
  assert.equal(routeByMethod.get('review/start').localStatus, 'diagnostic-only');
  assert.equal(routeByMethod.get('review/start').requiresApproval, false);
  assert.equal(routeByMethod.get('attestation/generate').localStatus, 'diagnostic-only');
  assert.equal(routeByMethod.get('attestation/generate').requiresApproval, false);
  assert.equal(routeByMethod.get('thread/realtime/listVoices').group, 'realtime');
  assert.equal(routeByMethod.get('thread/realtime/listVoices').readOnly, true);
  assert.equal(routeByMethod.get('thread/realtime/start').localStatus, 'diagnostic-only');
  assert.equal(routeByMethod.get('thread/realtime/start').requiresApproval, false);
  assert.equal(routeByMethod.get('thread/realtime/appendAudio').localStatus, 'diagnostic-only');
  assert.equal(routeByMethod.get('thread/realtime/appendAudio').requiresApproval, false);
});

